-- Yahoo!フリマ（谷川④・腕時計）マスター本番登録 2026-11-11（v3 承認版 + 在庫取得停止・自動出品停止）
-- v3変更: カテゴリー7件（スマートウォッチ本体40976を31387/Wristwatch/Unisex Adultsで有効化）、Apple・HUAWEI・Google・Xiaomiを有効化
-- 前提: scrape_worker / check_remaining_ebay / publish_ebay 等の ＰａｙＰａｙフリマ 分岐を先に本番反映すること（先に流すとジョブがメルカリ処理に流れる）
SET XACT_ABORT ON;
BEGIN TRAN;

-- 1) 仕入先。publish_priority=4（ラクマ1・メルカリshops2・メルカリ3より後。出品候補はアカウントごとに最小の優先度の仕入先だけになる）
--    is_scrape_stopped=1: fetch_active / fetch_sold のジョブを積まない（定期の在庫取得を始めない。出品中の商品は check_remaining が個別に確認する）

-- 1-2) 自動出品の停止: 全eBayアカウントの出品候補から Yahoo!フリマ を外す（テスト出品は専用スクリプトで件数を指定して行う）
SELECT a.account, 'Y', N'Yahoo!フリマ 段階導入（2026-11-11）: 通常運用の承認まで自動出品しない'
FROM mst.ebay_accounts a
WHERE NOT EXISTS (SELECT 1 FROM mst.ebay_account_excluded_vendors x WHERE x.account = a.account AND x.vendor_code = 'Y');

-- 2) 検索カテゴリー（Yahoo!フリマ genreCategoryIds）と eBayカテゴリー・Type・Department

-- 3) ブランド対応（検索用ID。eBayのBrandは presets_brand.default_brand_en が使われる）
-- 対応不可: 3291 パナソニック
-- 対応不可: 3548 マルマン
-- 対応不可: 6118 MIDO

-- 4) ラクマ専用で腕時計に所属しているブランドを Yahoo!フリマにも適用（要判断。使わないなら削除）

-- 件数確認してから COMMIT（presets_lookup は inventory_loop のサイクル開始時の refresh_presets_lookup で自動生成）
SELECT (SELECT COUNT(*) FROM mst.vendors WHERE vendor_name=N'ＰａｙＰａｙフリマ') AS vendors, (SELECT COUNT(*) FROM mst.presets_categories WHERE vendor_group=N'ＰａｙＰａｙフリマ') AS cats, (SELECT COUNT(*) FROM mst.category_group_categories WHERE vendor_group=N'ＰａｙＰａｙフリマ') AS cgc, (SELECT COUNT(*) FROM mst.vendor_brand_map WHERE vendor_name=N'ＰａｙＰａｙフリマ') AS vbm, (SELECT COUNT(*) FROM mst.brand_category_group_vendors WHERE vendor_name=N'ＰａｙＰａｙフリマ') AS bcgv, (SELECT COUNT(*) FROM mst.ebay_account_excluded_vendors WHERE vendor_code='Y') AS excluded_accounts;
-- 期待値: vendors=1, cats=7, cgc=7, vbm=117, bcgv=40, excluded_accounts=mst.ebay_accounts の件数
-- COMMIT;  /  ROLLBACK;